147	    /**
148	     * The request header carrying the caller's idempotency key. When a create is repeated with a key
149	     * already seen, the originally created owner is returned with 200 instead of a duplicate being
150	     * created (see {@link #addOwner(OwnerFieldsDto)} and {@link IdempotencyKeyStore}).
151	     */
152	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
153	
154	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
155	    @Override
156	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
157	        String idempotencyKey = currentIdempotencyKey();
158	        Optional<Owner> existing = idempotencyKeyStore.find(idempotencyKey)
159	            .map(this.clinicService::findOwnerById);
160	        if (existing.isPresent()) {
161	            return ownerResponse(existing.get(), HttpStatus.OK);
162	        }
163	        Owner owner = createOwner(ownerFieldsDto);
164	        idempotencyKeyStore.record(idempotencyKey, owner.getId());
165	        return ownerResponse(owner, HttpStatus.CREATED);
166	    }
167	
168	    /**
169	     * Reads the {@code Idempotency-Key} header from the current request, or {@code null} when no
170	     * request is bound or the header is absent. Held in one place so the create endpoint can decide,
171	     * from the key alone, whether a create is a first occurrence or a repeat to be served from the
172	     * originally created owner.
173	     *
174	     * @return the request's idempotency key, or {@code null} when none was supplied
175	     */
176	    private String currentIdempotencyKey() {
177	        if (RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes) {
178	            return attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
179	        }
180	        return null;
181	    }
182	
183	    /**
184	     * Validates and normalizes the submitted owner fields, builds the owner, enforces the create-time
185	     * duplicate rules and persists it, returning the saved owner. This holds the whole "make and store
186	     * a new owner" flow in one place, separate from turning that owner into an HTTP response
187	     * ({@link #ownerResponse(Owner, HttpStatus)}), so the create endpoint reads as "create the owner,
188	     * then respond" and the persisted owner is available to callers that need it beyond the response.
189	     *
190	     * @param ownerFieldsDto the submitted owner fields, normalized in place as part of the create
191	     * @return the persisted owner, with its derived fields populated
192	     */
193	    private Owner createOwner(OwnerFieldsDto ownerFieldsDto) {
194	        normalizeAddress(ownerFieldsDto);
195	        rejectBlankOwnerFields(ownerFieldsDto);
196	        rejectDisposableEmailDomain(ownerFieldsDto.getEmail());
197	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
198	        rejectInvalidPostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
199	        rejectCityAtCapacity(ownerFieldsDto.getCity());
200	        rejectFutureRegistrationDate(ownerFieldsDto.getRegistrationDate());
201	        LocalDate registrationDate = businessDay(effectiveRegistrationDate(ownerFieldsDto.getRegistrationDate()));
202	        rejectDailyRegistrationLimit(registrationDate);
203	        String normalizedTelephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
204	        ownerFieldsDto.setTelephone(normalizedTelephone);
205	        String normalizedEmail = emailNormalizer.normalize(ownerFieldsDto.getEmail());
206	        ownerFieldsDto.setEmail(normalizedEmail);
207	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
208	        owner.setRegistrationDate(registrationDate);
209	        owner.setCustomerCode(customerCode(owner));
210	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
211	        owner.setHouseholdId(householdId(owner));
212	        rejectDuplicateIdentity(owner);
213	        rejectHouseholdDuplicate(owner, sharesHousehold);
214	        owner.setPossibleDuplicateOf(sharesHousehold ? null : possibleDuplicateOf(owner));
215	        this.clinicService.saveOwner(owner);
216	        owner.setHouseholdSize(householdSize(owner));
217	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
218	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
219	            membershipLevel(owner), ownerMapper.membershipNumber(owner));
220	        return owner;
221	    }
222	
223	    /**
224	     * Builds the response for an owner: its derived-field DTO (see
225	     * {@link #toOwnerDtoWithDerivedFields(Owner)}) as the body and a {@code Location} header pointing at
226	     * the owner's canonical URL, returned with the given {@code status}. Assembling the response in one
227	     * place keeps "what to return for an owner" separate from the create flow that produced it, so any
228	     * path that returns an owner does so identically (differing only in the status it carries).
229	     *
230	     * @param owner the persisted owner to represent
231	     * @param status the HTTP status to return
232	     * @return the owner response with its body, {@code Location} header and status
233	     */
234	    private ResponseEntity<OwnerDto> ownerResponse(Owner owner, HttpStatus status) {
235	        OwnerDto ownerDto = toOwnerDtoWithDerivedFields(owner);
236	        HttpHeaders headers = new HttpHeaders();
237	        headers.setLocation(UriComponentsBuilder.newInstance()
238	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
239	        return new ResponseEntity<>(ownerDto, headers, status);
240	    }
