331	    /**
332	     * Loads the owner with the given id and, when it exists, produces the response through
333	     * {@code action}; when no such owner exists a {@code 404 Not Found} is returned instead. The
334	     * single-owner endpoints share this "find the owner or report 404" preamble, so the lookup and
335	     * the not-found response are written in exactly one place rather than copied into each method.
336	     *
337	     * @param ownerId the id of the owner to load
338	     * @param action builds the response for an existing owner
339	     * @param <T> the response body type
340	     * @return the result of {@code action} for an existing owner, otherwise a 404 response
341	     */
342	    private <T> ResponseEntity<T> withOwner(Integer ownerId, Function<Owner, ResponseEntity<T>> action) {
343	        Owner owner = this.clinicService.findOwnerById(ownerId);
344	        if (owner == null) {
345	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
346	        }
347	        return action.apply(owner);
348	    }
349	
350	    /**
351	     * Maps a persisted owner to its {@link OwnerDto} and populates the read-only fields that are
352	     * derived from server-side state rather than stored columns (the {@code bulkSignupWarning} flag,
353	     * the {@code identityKey} and the {@code possibleDuplicate} pair), and re-applies the owner's
354	     * {@code membershipLevel} through the controller ({@link #membershipLevel(Owner)}). Both the
355	     * create endpoint and the single-owner read endpoint return their owner through this method, so
356	     * an owner is decorated identically on either path and each derived field is computed in exactly
357	     * one place.
358	     *
359	     * @param owner the persisted owner to represent
360	     * @return the owner DTO with its derived read-only fields populated
361	     */
362	    private OwnerDto toOwnerDtoWithDerivedFields(Owner owner) {
363	        owner.setHouseholdSize(householdSize(owner));
364	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
365	        ownerDto.setMembershipLevel(membershipLevel(owner));
366	        ownerDto.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
367	        ownerDto.setIdentityKey(identityKey(owner));
368	        Integer possibleDuplicateOf = owner.getPossibleDuplicateOf();
369	        ownerDto.setPossibleDuplicate(possibleDuplicateOf != null);
370	        ownerDto.setPossibleDuplicateOf(possibleDuplicateOf);
371	        return ownerDto;
372	    }
373	
374	    /**
375	     * The {@code membershipLevel} reported for a single owner. Starts from the owner-local derivation
376	     * in {@link OwnerMapper#membershipLevel(Owner)} (the level from the owner's own membership points),
377	     * routed through the controller so the create audit log and the single-owner response agree on one
378	     * value. Unlike the mapper - which sees only the owner - the controller can reach the rest of the
379	     * clinic, so this is the single place a reported membership level is shaped by cross-owner context.
380	     *
381	     * <p>Household ceiling: the reported level is capped at one above the current maximum
382	     * {@linkplain #householdMemberLevel(Owner) level} among the owner's <em>existing</em>
383	     * {@link #householdMembers(Owner) household members} (those sharing its {@code householdId}, other
384	     * than the owner itself). With no existing household member no cap applies and the owner-local level
385	     * is reported unchanged. The cap uses each member's own owner-local level (not their reported,
386	     * capped level), so it depends only on the members' own points and cannot recurse.
387	     *
388	     * @param owner the owner whose reported membership level is wanted
389	     * @return the owner's membership level, capped at one above its household maximum
390	     */
391	    private Integer membershipLevel(Owner owner) {
392	        int ownLevel = ownerMapper.membershipLevel(owner);
393	        java.util.OptionalInt maxHouseholdLevel = householdMembers(owner).stream()
394	            .filter(member -> !java.util.Objects.equals(member.getId(), owner.getId()))
395	            .mapToInt(this::householdMemberLevel)
396	            .max();
397	        if (maxHouseholdLevel.isEmpty()) {
398	            return ownLevel;
399	        }
400	        return Math.min(ownLevel, maxHouseholdLevel.getAsInt() + 1);
401	    }
402	
403	    /**
404	     * The owner-local membership level of a household member, used only as an input to the household
405	     * ceiling in {@link #membershipLevel(Owner)}. The member's {@link Owner#getHouseholdSize()
406	     * household size} is set from its household before the level is derived, so the member's household
407	     * factor is accounted for exactly as it is when the member is reported on its own; the level itself
408	     * comes from the owner-local {@link OwnerMapper#membershipLevel(Owner)}.
409	     *
410	     * @param member an existing member of an owner's household
411	     * @return the member's owner-local membership level
412	     */
413	    private int householdMemberLevel(Owner member) {
414	        member.setHouseholdSize(householdSize(member));
415	        return ownerMapper.membershipLevel(member);
416	    }
417	
418	    /**
419	     * Canonicalizes the submitted address in place before it is validated, stored and returned, so
420	     * every later step - the required-field check, the persisted value and the response - sees the
421	     * single normalized form produced by {@link AddressNormalizer#normalize(String)} (see that method
422	     * for the trim/collapse/upper-case/abbreviation rules). Normalizing once here, at the head of the
423	     * create flow, keeps address canonicalization in exactly one place rather than spread across the
424	     * steps that read the address.
425	     *
426	     * <p>An address may be supplied either as the structured {@code addressLine1} (with an optional
427	     * {@code addressLine2}) or as the single flat {@code address}, the latter kept for backward
428	     * compatibility. Whichever address fields are supplied are normalized, and the structured fields
429	     * are preferred when present: the flat {@code address} returned is composed as the normalized
430	     * {@code addressLine1}, with a single space and the normalized {@code addressLine2} appended when an
431	     * {@code addressLine2} is present; only when no {@code addressLine1} is supplied does the flat
432	     * {@code address} retain its own normalized value.
433	     *
434	     * @param ownerFieldsDto the submitted owner fields, whose address fields are replaced with their normalized form
435	     */
436	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
437	        String addressLine1 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
438	        String addressLine2 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
439	        String flatAddress = addressNormalizer.normalize(ownerFieldsDto.getAddress());
440	        ownerFieldsDto.setAddressLine1(addressLine1);
441	        ownerFieldsDto.setAddressLine2(addressLine2);
442	        if (addressLine1 != null && !addressLine1.isBlank()) {
443	            String composed = addressLine2 != null && !addressLine2.isBlank()
444	                ? addressLine1 + " " + addressLine2
445	                : addressLine1;
446	            ownerFieldsDto.setAddress(composed);
447	        } else {
448	            ownerFieldsDto.setAddress(flatAddress);
449	        }
450	    }
451	
452	    /**
453	     * Rejects an owner whose required text fields are blank (whitespace-only). Missing (null)
454	     * and empty fields are already rejected by Bean Validation on {@link OwnerFieldsDto}; this
455	     * closes the gap for {@code address} and {@code city}, whose values may be non-empty yet
456	     * blank (e.g. {@code "   "}). The offending field names are reported through an
457	     * {@link InvalidOwnerFieldsException}, which the {@code ExceptionControllerAdvice} renders
458	     * as a 400 response carrying an {@code errors} array of field names.
459	     *
460	     * @param ownerFieldsDto the submitted owner fields
461	     * @throws InvalidOwnerFieldsException if one or more required fields are blank
462	     */
463	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
464	        List<String> blankFields = new ArrayList<>();
465	        addIfBlank(blankFields, "firstName", ownerFieldsDto.getFirstName());
466	        addIfBlank(blankFields, "lastName", ownerFieldsDto.getLastName());
467	        addRequiredAddress(blankFields, ownerFieldsDto);
468	        addIfBlank(blankFields, "city", ownerFieldsDto.getCity());
469	        addIfBlank(blankFields, "telephone", ownerFieldsDto.getTelephone());
470	        if (!blankFields.isEmpty()) {
471	            throw new InvalidOwnerFieldsException(blankFields);
472	        }
473	    }
474	
475	    private void addIfBlank(List<String> blankFields, String field, String value) {
476	        if (value != null && value.isBlank()) {
477	            blankFields.add(field);
478	        }
479	    }
480	
481	    /**
482	     * Records the address requirement's offending field name(s) into {@code blankFields}. An owner
483	     * must supply an address in EITHER accepted form: the structured {@code addressLine1} or the flat
484	     * {@code address} (kept for backward compatibility). The requirement is satisfied when at least one
485	     * of those is present and non-blank; only when both are missing or blank is {@code address} reported
486	     * as the offending field. Holding the "an owner must have an address" rule in its own method - rather
487	     * than a bare entry in the field list - gives it one place to live as the accepted address forms grow.
488	     *
489	     * @param blankFields the accumulating list of blank required-field names
490	     * @param ownerFieldsDto the submitted owner fields
491	     */
492	    private void addRequiredAddress(List<String> blankFields, OwnerFieldsDto ownerFieldsDto) {
493	        if (isBlank(ownerFieldsDto.getAddressLine1()) && isBlank(ownerFieldsDto.getAddress())) {
494	            blankFields.add("address");
495	        }
496	    }
497	
498	    private boolean isBlank(String value) {
499	        return value == null || value.isBlank();
500	    }
501	
502	    /**
503	     * Rejects an owner whose {@code email} domain is on the disposable-domain blocklist
504	     * ({@code mailinator.com}, {@code tempmail.com}, {@code guerrillamail.com}). Email is validated
