546	    /**
547	     * Number of leading hex characters of the identity hash retained as the {@code HASH8} segment of
548	     * the {@code customerCode}.
549	     */
550	    private static final int CUSTOMER_CODE_HASH_LENGTH = 8;
551	
552	    /**
553	     * Builds the {@code customerCode} assigned to a newly created owner, formatted
554	     * {@code '<REGION>-<HASH8>'}: {@code REGION} is the owner's canonical region code resolved from
555	     * its {@code postcode} (falling back to its {@code city}) through the shared
556	     * {@link Region#code(String, String)}, and {@code HASH8} is the first 8 upper-case hex characters
557	     * of the SHA-256 digest of the owner's normalized telephone followed by its last name
558	     * (e.g. {@code 'NSW-1A2B3C4D'}). When this base code collides with an existing owner's
559	     * {@code customerCode}, {@code '-<n>'} is appended with the smallest {@code n} of 2 or more that
560	     * makes the result unique (e.g. {@code 'NSW-1A2B3C4D-2'}), so distinct owners always receive
561	     * distinct customer codes.
562	     *
563	     * @param owner the owner being created, with its telephone already normalized
564	     * @return the formatted, de-duplicated customer code
565	     */
566	    private String customerCode(Owner owner) {
567	        String region = Region.code(owner.getPostcode(), owner.getCity());
568	        String hash8 = sha256Hasher.hexPrefix(owner.getTelephone() + owner.getLastName(), CUSTOMER_CODE_HASH_LENGTH);
569	        String base = region + "-" + hash8;
570	        return deduplicateCustomerCode(base);
571	    }
