807	    /**
808	     * Rejects a create request that would re-register an existing household member unless it declares
809	     * the shared household with {@code sharesHousehold}. The household is keyed on
810	     * {@code (lastName, postcode)} through the deterministic {@link #householdId(Owner)}, so an existing
811	     * owner with the same last name and postcode is a member of the same household. A new owner that
812	     * matches an existing member of that household on its <em>canonical telephone</em> (see
813	     * {@link TelephoneNormalizer#canonicalize(String)}) is a household duplicate and is rejected with a
814	     * 409 (via {@link DuplicateOwnerIdentityException}). A member carrying a <em>different</em> telephone
815	     * is a distinct person in the same household: it is allowed and surfaced instead as a soft
816	     * {@code possibleDuplicate} (see {@link #possibleDuplicateOf(Owner)}), which is what lets a household
817	     * hold more than one owner. Setting {@code sharesHousehold} bypasses this block, so the owner is
818	     * created as a declared household member. Owners without a {@code householdId} (e.g. no postcode)
819	     * have no household to collide with and are always allowed.
820	     *
821	     * @param owner the fully-populated owner being created (household id set, telephone normalized)
822	     * @param sharesHousehold whether the request declared it shares an existing household
823	     * @throws DuplicateOwnerIdentityException if a household member with the same telephone exists and it was not declared
824	     */
825	    private void rejectHouseholdDuplicate(Owner owner, boolean sharesHousehold) {
826	        if (sharesHousehold) {
827	            return;
828	        }
829	        String household = owner.getHouseholdId();
830	        if (household == null) {
831	            return;
832	        }
833	        String telephone = telephoneNormalizer.canonicalize(owner.getTelephone());
834	        boolean sameTelephoneMember = this.clinicService.findAllOwners().stream()
835	            .filter(existing -> !existing.isDeleted())
836	            .filter(existing -> household.equals(existing.getHouseholdId()))
837	            .anyMatch(existing -> java.util.Objects.equals(telephone,
838	                telephoneNormalizer.canonicalize(existing.getTelephone())));
839	        if (sameTelephoneMember) {
840	            throw new DuplicateOwnerIdentityException(identityKey(owner));
841	        }
842	    }
