844	    /**
845	     * Computes the soft-match {@code possibleDuplicateOf} for a newly created owner: the id of the
846	     * first existing owner that shares this owner's {@code lastName} (compared case-insensitively) and
847	     * {@code postcode} while carrying a <em>different</em> telephone (compared by canonical E.164 form,
848	     * see {@link TelephoneNormalizer#canonicalize(String)}), or {@code null} when no such owner exists.
849	     * The check runs only after the exact-identity duplicate check ({@link #rejectDuplicateIdentity(Owner)})
850	     * has passed, so a shared last-name-and-postcode with the same telephone has already been rejected as
851	     * a hard duplicate and can never surface here. A blank {@code postcode} never matches, since two
852	     * owners without a postcode do not share one. The captured id is stored on the new owner and surfaced
853	     * as the read-only {@code possibleDuplicate} / {@code possibleDuplicateOf} fields.
854	     *
855	     * @param owner the fully-populated owner being created (telephone normalized)
856	     * @return the id of the first soft-matching existing owner, or {@code null} when none matches
857	     */
858	    private Integer possibleDuplicateOf(Owner owner) {
859	        if (owner.getPostcode() == null || owner.getPostcode().isBlank()) {
860	            return null;
861	        }
862	        String telephone = telephoneNormalizer.canonicalize(owner.getTelephone());
863	        return this.clinicService.findAllOwners().stream()
864	            .filter(existing -> equalsIgnoreCase(existing.getLastName(), owner.getLastName())
865	                && owner.getPostcode().equals(existing.getPostcode())
866	                && !java.util.Objects.equals(telephone, telephoneNormalizer.canonicalize(existing.getTelephone())))
867	            .map(Owner::getId)
868	            .filter(java.util.Objects::nonNull)
869	            .findFirst()
870	            .orElse(null);
871	    }
