886	    private String identityKey(Owner owner) {
887	        String telephone = telephoneNormalizer.canonicalize(owner.getTelephone());
888	        String normalizedEmail = emailNormalizer.normalize(owner.getEmail());
889	        String email = normalizedEmail == null ? "" : normalizedEmail;
890	        String household = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
891	        return telephone + "|" + email + "|" + household;
