147	    /**
148	     * The request header carrying the caller's idempotency key. When a create is repeated with a key
149	     * already seen, the originally created owner is returned with 200 instead of a duplicate being
150	     * created (see {@link #addOwner(OwnerFieldsDto)} and {@link IdempotencyKeyStore}).
151	     */
152	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
153	
154	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
155	    @Override
156	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
157	        String idempotencyKey = currentIdempotencyKey();
158	        Optional<Owner> existing = idempotencyKeyStore.find(idempotencyKey)
159	            .map(this.clinicService::findOwnerById);
160	        if (existing.isPresent()) {
161	            return ownerResponse(existing.get(), HttpStatus.OK);
162	        }
163	        Owner owner = createOwner(ownerFieldsDto);
164	        idempotencyKeyStore.record(idempotencyKey, owner.getId());
165	        return ownerResponse(owner, HttpStatus.CREATED);
166	    }
