168	    /**
169	     * Reads the {@code Idempotency-Key} header from the current request, or {@code null} when no
170	     * request is bound or the header is absent. Held in one place so the create endpoint can decide,
171	     * from the key alone, whether a create is a first occurrence or a repeat to be served from the
172	     * originally created owner.
173	     *
174	     * @return the request's idempotency key, or {@code null} when none was supplied
175	     */
176	    private String currentIdempotencyKey() {
177	        if (RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes) {
178	            return attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
179	        }
180	        return null;
181	    }
