183	    /**
184	     * Validates and normalizes the submitted owner fields, builds the owner, enforces the create-time
185	     * duplicate rules and persists it, returning the saved owner. This holds the whole "make and store
186	     * a new owner" flow in one place, separate from turning that owner into an HTTP response
187	     * ({@link #ownerResponse(Owner, HttpStatus)}), so the create endpoint reads as "create the owner,
188	     * then respond" and the persisted owner is available to callers that need it beyond the response.
189	     *
190	     * @param ownerFieldsDto the submitted owner fields, normalized in place as part of the create
191	     * @return the persisted owner, with its derived fields populated
192	     */
193	    private Owner createOwner(OwnerFieldsDto ownerFieldsDto) {
194	        normalizeAddress(ownerFieldsDto);
195	        rejectBlankOwnerFields(ownerFieldsDto);
196	        rejectDisposableEmailDomain(ownerFieldsDto.getEmail());
197	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
198	        rejectInvalidPostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
199	        rejectCityAtCapacity(ownerFieldsDto.getCity());
200	        rejectFutureRegistrationDate(ownerFieldsDto.getRegistrationDate());
201	        LocalDate registrationDate = businessDay(effectiveRegistrationDate(ownerFieldsDto.getRegistrationDate()));
202	        rejectDailyRegistrationLimit(registrationDate);
203	        String normalizedTelephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
204	        ownerFieldsDto.setTelephone(normalizedTelephone);
205	        String normalizedEmail = emailNormalizer.normalize(ownerFieldsDto.getEmail());
206	        ownerFieldsDto.setEmail(normalizedEmail);
207	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
208	        owner.setRegistrationDate(registrationDate);
209	        owner.setCustomerCode(customerCode(owner));
210	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
211	        owner.setHouseholdId(householdId(owner));
212	        rejectDuplicateIdentity(owner);
213	        rejectHouseholdDuplicate(owner, sharesHousehold);
214	        owner.setPossibleDuplicateOf(sharesHousehold ? null : possibleDuplicateOf(owner));
215	        this.clinicService.saveOwner(owner);
216	        owner.setHouseholdSize(householdSize(owner));
217	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
218	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
219	            membershipLevel(owner), ownerMapper.membershipNumber(owner));
220	        return owner;
221	    }
