227	     * place keeps "what to return for an owner" separate from the create flow that produced it, so any
228	     * path that returns an owner does so identically (differing only in the status it carries).
229	     *
230	     * @param owner the persisted owner to represent
231	     * @param status the HTTP status to return
232	     * @return the owner response with its body, {@code Location} header and status
233	     */
234	    private ResponseEntity<OwnerDto> ownerResponse(Owner owner, HttpStatus status) {
235	        OwnerDto ownerDto = toOwnerDtoWithDerivedFields(owner);
236	        HttpHeaders headers = new HttpHeaders();
237	        headers.setLocation(UriComponentsBuilder.newInstance()
238	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
239	        return new ResponseEntity<>(ownerDto, headers, status);
240	    }
