452	    /**
453	     * Rejects an owner whose required text fields are blank (whitespace-only). Missing (null)
454	     * and empty fields are already rejected by Bean Validation on {@link OwnerFieldsDto}; this
455	     * closes the gap for {@code address} and {@code city}, whose values may be non-empty yet
456	     * blank (e.g. {@code "   "}). The offending field names are reported through an
457	     * {@link InvalidOwnerFieldsException}, which the {@code ExceptionControllerAdvice} renders
458	     * as a 400 response carrying an {@code errors} array of field names.
459	     *
460	     * @param ownerFieldsDto the submitted owner fields
461	     * @throws InvalidOwnerFieldsException if one or more required fields are blank
462	     */
463	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
464	        List<String> blankFields = new ArrayList<>();
465	        addIfBlank(blankFields, "firstName", ownerFieldsDto.getFirstName());
466	        addIfBlank(blankFields, "lastName", ownerFieldsDto.getLastName());
467	        addRequiredAddress(blankFields, ownerFieldsDto);
468	        addIfBlank(blankFields, "city", ownerFieldsDto.getCity());
469	        addIfBlank(blankFields, "telephone", ownerFieldsDto.getTelephone());
470	        if (!blankFields.isEmpty()) {
471	            throw new InvalidOwnerFieldsException(blankFields);
472	        }
473	    }
474	
475	    private void addIfBlank(List<String> blankFields, String field, String value) {
476	        if (value != null && value.isBlank()) {
477	            blankFields.add(field);
478	        }
479	    }
480	
481	    /**
482	     * Records the address requirement's offending field name(s) into {@code blankFields}. An owner
483	     * must supply an address in EITHER accepted form: the structured {@code addressLine1} or the flat
484	     * {@code address} (kept for backward compatibility). The requirement is satisfied when at least one
485	     * of those is present and non-blank; only when both are missing or blank is {@code address} reported
486	     * as the offending field. Holding the "an owner must have an address" rule in its own method - rather
487	     * than a bare entry in the field list - gives it one place to live as the accepted address forms grow.
488	     *
489	     * @param blankFields the accumulating list of blank required-field names
490	     * @param ownerFieldsDto the submitted owner fields
491	     */
492	    private void addRequiredAddress(List<String> blankFields, OwnerFieldsDto ownerFieldsDto) {
493	        if (isBlank(ownerFieldsDto.getAddressLine1()) && isBlank(ownerFieldsDto.getAddress())) {
494	            blankFields.add("address");
495	        }
496	    }
497	
498	    private boolean isBlank(String value) {
499	        return value == null || value.isBlank();
500	    }
