502	    /**
503	     * Rejects an owner whose {@code email} domain is on the disposable-domain blocklist
504	     * ({@code mailinator.com}, {@code tempmail.com}, {@code guerrillamail.com}). Email is validated
505	     * only when present, so an owner created without one is accepted unchanged; syntactic validity is
506	     * already enforced by Bean Validation's {@code @Email} constraint on {@link OwnerFieldsDto}, so
507	     * this only rejects an otherwise well-formed address that uses a throwaway provider (see
508	     * {@link DisposableEmailDomains#isDisposable(String)} for the case-insensitive domain match). A
509	     * blocklisted address is reported through a {@link DisposableEmailDomainException}, which the
510	     * {@code ExceptionControllerAdvice} renders as a 400 response naming the {@code email} field.
511	     *
512	     * @param email the supplied email, or {@code null} when omitted
513	     * @throws DisposableEmailDomainException if the email's domain is blocklisted
514	     */
515	    private void rejectDisposableEmailDomain(String email) {
516	        if (disposableEmailDomains.isDisposable(email)) {
517	            throw new DisposableEmailDomainException(email);
518	        }
519	    }
