521	    /**
522	     * Validates the owner's optional {@code postcode} against its {@code city} region. Postcode is
523	     * validated only when present, so an owner created without one is accepted unchanged. A supplied
524	     * postcode is already constrained to four digits by Bean Validation on {@link OwnerFieldsDto}; this
525	     * additionally rejects a well-formed postcode that is out of range for the city's region using the
526	     * shared {@link Region#acceptsPostcode(int) region-to-postcode} table ({@code NSW 2000-2099},
527	     * {@code VIC 3000-3099}, {@code QLD 4000-4099}). A city with no known region accepts any 4-digit
528	     * postcode. An out-of-range postcode is reported through an {@link InvalidOwnerPostcodeException},
529	     * which the {@code ExceptionControllerAdvice} renders as a 400 response.
530	     *
531	     * @param city the city of the owner being created
532	     * @param postcode the supplied postcode, or {@code null} when omitted
533	     * @throws InvalidOwnerPostcodeException if the postcode is out of range for the city's region
534	     */
535	    private void rejectInvalidPostcode(String city, String postcode) {
536	        if (postcode == null || postcode.isBlank()) {
537	            return;
538	        }
539	        Region.forCity(city).ifPresent(region -> {
540	            if (!region.acceptsPostcode(Integer.parseInt(postcode))) {
541	                throw new InvalidOwnerPostcodeException(postcode, city);
542	            }
543	        });
544	    }
