597	    /**
598	     * Counts how many existing owners already share the given {@code firstName} and {@code lastName},
599	     * compared case-insensitively (using {@link java.util.Locale#ROOT}-independent
600	     * {@link String#equalsIgnoreCase(String)}). The count reflects the owners present before the
601	     * current create, so a name that is unique on create yields {@code 0}. The value is stored on the
602	     * new owner and surfaced as the read-only {@code namesakeCount} field.
603	     *
604	     * @param firstName the first name of the owner being created
605	     * @param lastName the last name of the owner being created
606	     * @return the number of existing owners with the same first and last name (case-insensitive)
607	     */
608	    private int namesakeCount(String firstName, String lastName) {
609	        return (int) countOwners(owner -> equalsIgnoreCase(owner.getFirstName(), firstName)
610	            && equalsIgnoreCase(owner.getLastName(), lastName));
611	    }
