623	    /**
624	     * Rejects a create request whose city already contains {@link #MAX_OWNERS_PER_CITY} or more
625	     * owners. Existing owners are matched to the requested city case-insensitively (using
626	     * {@link java.util.Locale#ROOT}-independent {@link String#equalsIgnoreCase(String)}), mirroring
627	     * the per-city counting used for the customer code. A city at capacity is reported through an
628	     * {@link OwnerCityAtCapacityException}, which the {@code ExceptionControllerAdvice} renders as a
629	     * 409 Conflict response.
630	     *
631	     * @param city the city of the owner being created
632	     * @throws OwnerCityAtCapacityException if the city already holds the maximum number of owners
633	     */
634	    private void rejectCityAtCapacity(String city) {
635	        if (ownersInCity(city) >= MAX_OWNERS_PER_CITY) {
636	            throw new OwnerCityAtCapacityException(city);
637	        }
