652	    /**
653	     * The maximum number of owners that may be registered on a single day. Once this many owners
654	     * already carry a given {@code registrationDate}, further owners for that date are rejected by
655	     * {@link #rejectDailyRegistrationLimit(LocalDate)}.
656	     */
657	    private static final long MAX_OWNERS_PER_DAY = 100L;
