659	    /**
660	     * Resolves the effective registration date for a create request: the value supplied in the
661	     * request when present, otherwise the server's current date. The result is the raw effective
662	     * date before the business-day adjustment applied by {@link #businessDay(LocalDate)}.
663	     *
664	     * @param suppliedDate the registration date from the request, or {@code null} when omitted
665	     * @return the supplied date, or today when none was supplied
666	     */
667	    private LocalDate effectiveRegistrationDate(LocalDate suppliedDate) {
668	        return suppliedDate != null ? suppliedDate : LocalDate.now();
669	    }
