671	    /**
672	     * Rejects a create request whose supplied {@code registrationDate} lies after the server's
673	     * current date. A registration date may be supplied to backdate a create - and is defaulted to
674	     * today when omitted - but it may never be in the future. The check is applied to the raw
675	     * supplied value before the business-day adjustment ({@link #businessDay(LocalDate)}), so a
676	     * future date is rejected regardless of how that adjustment would move it. A future date is
677	     * reported through a {@link FutureRegistrationDateException}, which the
678	     * {@code ExceptionControllerAdvice} renders as a 400 Bad Request response naming the
679	     * {@code registrationDate} field.
680	     *
681	     * @param suppliedDate the registration date from the request, or {@code null} when omitted
682	     * @throws FutureRegistrationDateException if the supplied date is later than the server date
683	     */
684	    private void rejectFutureRegistrationDate(LocalDate suppliedDate) {
685	        if (suppliedDate != null && suppliedDate.isAfter(LocalDate.now())) {
686	            throw new FutureRegistrationDateException(suppliedDate);
687	        }
688	    }
