690	    /**
691	     * The fixed list of public holidays that are not business days. A registration date that lands
692	     * on one of these is rolled forward by {@link #businessDay(LocalDate)} to the next non-holiday
693	     * business day, exactly as it is rolled forward off a weekend.
694	     */
695	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
696	        LocalDate.of(2026, 1, 1),
697	        LocalDate.of(2026, 1, 26),
698	        LocalDate.of(2026, 4, 25),
699	        LocalDate.of(2026, 12, 25),
700	        LocalDate.of(2026, 12, 28));
701	
702	    /**
703	     * Adjusts a date so it falls on a business day, rolling forward off weekends and public
704	     * holidays. A Saturday, Sunday or {@link #PUBLIC_HOLIDAYS listed public holiday} is rolled
705	     * forward one day at a time until the first non-holiday weekday is reached; any other weekday is
706	     * returned unchanged. Applied to the effective registration date so that a weekend or holiday
707	     * value - whether supplied in the request or defaulted to the server date - is stored as the
708	     * next business day, and every value derived from the registration date (such as the membership
709	     * number's year segment and the daily create-limit bucket) uses the adjusted business day.
710	     *
711	     * @param date the effective registration date
712	     * @return the same date when it is a non-holiday weekday, otherwise the next business day
713	     */
714	    private LocalDate businessDay(LocalDate date) {
715	        while (isNonBusinessDay(date)) {
716	            date = date.plusDays(1);
717	        }
718	        return date;
719	    }
720	
721	    /**
722	     * Whether the given date is a weekend day or a listed public holiday, and so not a business day.
723	     *
724	     * @param date the date to test
725	     * @return {@code true} for a Saturday, Sunday or {@link #PUBLIC_HOLIDAYS listed public holiday}
726	     */
727	    private boolean isNonBusinessDay(LocalDate date) {
728	        DayOfWeek dayOfWeek = date.getDayOfWeek();
729	        return dayOfWeek == DayOfWeek.SATURDAY
730	            || dayOfWeek == DayOfWeek.SUNDAY
731	            || PUBLIC_HOLIDAYS.contains(date);
732	    }
