734	    /**
735	     * Rejects a create request once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
736	     * created on the given day, counted by {@code registrationDate}. A day at capacity is reported
737	     * through a {@link DailyOwnerRegistrationLimitException}, which the {@code ExceptionControllerAdvice}
738	     * renders as a 429 Too Many Requests response.
739	     *
740	     * @param date the registration date of the owner being created (today)
741	     * @throws DailyOwnerRegistrationLimitException if the day already holds the maximum number of owners
742	     */
743	    private void rejectDailyRegistrationLimit(LocalDate date) {
744	        if (ownersRegisteredOn(date) >= MAX_OWNERS_PER_DAY) {
745	            throw new DailyOwnerRegistrationLimitException(date);
746	        }
747	    }
748	
749	    /**
750	     * Counts the existing owners whose {@code registrationDate} equals the given day. Shared by the
751	     * hard daily create limit ({@link #rejectDailyRegistrationLimit(LocalDate)}) and the soft
752	     * {@code bulkSignupWarning} flag ({@link #bulkSignupWarning(LocalDate)}) so both accumulate a
753	     * day's owners identically.
754	     *
755	     * @param date the registration date to count owners for
756	     * @return the number of existing owners registered on that day
757	     */
758	    private long ownersRegisteredOn(LocalDate date) {
759	        return countOwners(owner -> date.equals(owner.getRegistrationDate()));
760	    }
761	
762	    /**
763	     * The soft daily create threshold above which the read-only {@code bulkSignupWarning} flag is
764	     * raised. Once more than this many owners share a {@code registrationDate}, that day is flagged
765	     * as unusually high volume - a warning well below the hard {@link #MAX_OWNERS_PER_DAY} cap.
766	     */
767	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
768	
769	    /**
770	     * Derives the read-only {@code bulkSignupWarning} flag for an owner: {@code true} when more than
771	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have been created (counted by
772	     * {@code registrationDate}) on the given day, otherwise {@code false}. Uses the same per-day
773	     * accumulation as {@link #rejectDailyRegistrationLimit(LocalDate)}. A {@code null} date (an owner
774	     * without a registration date, such as seed data) is never flagged.
775	     *
776	     * @param date the owner's registration date (the day it was created), or {@code null}
777	     * @return {@code true} if the day already holds more than the warning threshold of owners
778	     */
779	    private boolean bulkSignupWarning(LocalDate date) {
780	        if (date == null) {
781	            return false;
782	        }
783	        return ownersRegisteredOn(date) > BULK_SIGNUP_WARNING_THRESHOLD;
784	    }
