894	    /**
895	     * Finds the first existing owner that already carries the given comparison {@code key}, derived
896	     * from each owner by {@code keyExtractor}. Owners for which the extractor yields {@code null} are
897	     * ignored (a {@code null} key never equals the sought key). The create endpoint's duplicate
898	     * checks reduce both an existing owner and the owner being created to the same canonical key;
899	     * this returns the matched existing owner itself, so a caller can either reject the collision or
900	     * record which owner was matched. Owners flagged deleted (soft-deleted) are excluded, so a
901	     * collision with only a deleted owner is not reported and the create is allowed.
902	     *
903	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
904	     * @param key the canonical key of the owner being created
905	     * @return the first existing owner sharing the key, or empty when none does
906	     */
907	    private Optional<Owner> findExistingOwner(Function<Owner, String> keyExtractor, String key) {
908	        return this.clinicService.findAllOwners().stream()
909	            .filter(owner -> !owner.isDeleted())
910	            .filter(owner -> key.equals(keyExtractor.apply(owner)))
911	            .findFirst();
912	    }
913	
914	    /**
915	     * Reports whether any existing owner already carries the given comparison {@code key}, derived
916	     * from each owner by {@code keyExtractor} (see {@link #findExistingOwner(Function, String)}).
917	     * The create endpoint's duplicate checks use this to reduce both an existing owner and the owner
918	     * being created to the same canonical key and reject a match.
919	     *
920	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
921	     * @param key the canonical key of the owner being created
922	     * @return {@code true} if some existing owner shares the key
923	     */
924	    private boolean existingOwnerMatches(Function<Owner, String> keyExtractor, String key) {
925	        return findExistingOwner(keyExtractor, key).isPresent();
926	    }
