928	    /**
929	     * Counts the existing owners that satisfy the given {@code predicate}. The create endpoint's
930	     * count-based rules - the per-city capacity, the per-day create limit and the derived
931	     * {@code namesakeCount} - all accumulate owners over {@link ClinicService#findAllOwners()} and
932	     * differ only in the predicate they count by, so the scan-and-count is written in exactly one
933	     * place and each rule supplies just its own predicate.
934	     *
935	     * @param predicate the condition an owner must satisfy to be counted
936	     * @return the number of existing owners that satisfy the predicate
937	     */
938	    private long countOwners(Predicate<Owner> predicate) {
939	        return this.clinicService.findAllOwners().stream()
940	            .filter(predicate)
941	            .count();
942	    }
