22	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
23	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
24	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
25	    @Mapping(target = "initials", expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" + owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
26	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
27	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
28	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
29	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
30	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
31	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
32	    @Mapping(target = "locality", expression = "java(locality(owner))")
33	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
34	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
35	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
36	    @Mapping(target = "bulkSignupWarning", ignore = true)
37	    @Mapping(target = "identityKey", ignore = true)
38	    @Mapping(target = "possibleDuplicate", ignore = true)
39	    @Mapping(target = "possibleDuplicateOf", ignore = true)
40	    OwnerDto toOwnerDto(Owner owner);
41	
42	    /**
43	     * Derives the owner's {@code selfLink}: the canonical link to the owner, formatted
44	     * {@code '/api/owners/' + id}. Returns {@code null} when the owner has no id (e.g. an
45	     * unpersisted owner), in which case the field is absent from the response.
46	     *
47	     * @param owner the owner being mapped
48	     * @return the owner's self link, or {@code null} when the owner has no id
49	     */
50	    default String selfLink(Owner owner) {
51	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
52	    }
53	
54	    /**
55	     * Derives the owner's {@code salutation} from its optional {@code title} and its {@code lastName}:
56	     * the title, a single space and the last name when a title is present (e.g. {@code 'DR Franklin'}),
57	     * otherwise just the last name. A {@code null} or blank title yields the bare last name.
58	     *
59	     * @param owner the owner being mapped
60	     * @return the derived salutation
61	     */
62	    default String salutation(Owner owner) {
63	        String title = owner.getTitle();
64	        if (title == null || title.isBlank()) {
65	            return owner.getLastName();
66	        }
67	        return title + " " + owner.getLastName();
68	    }
69	
70	    /**
71	     * Derives the owner's {@code contactPreference} from the owner's own fields:
72	     * {@code EMAIL} when an email is present, otherwise {@code PHONE}.
73	     *
74	     * @param owner the owner being mapped
75	     * @return the derived contact preference
76	     */
77	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
78	        return hasEmail(owner) ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
79	    }
80	
81	    /**
82	     * Reports whether the owner has a usable {@code email}: present and not blank (whitespace-only).
83	     * The presence of an email drives several derived fields (such as the {@code contactPreference}
84	     * and the {@code membershipLevel}), so the "has an email" test is written in exactly one place
85	     * rather than repeated at each use.
86	     *
87	     * @param owner the owner being mapped
88	     * @return {@code true} when the owner has a non-blank email
89	     */
90	    default boolean hasEmail(Owner owner) {
91	        return owner.getEmail() != null && !owner.getEmail().isBlank();
92	    }
93	
94	    /**
95	     * Derives the owner's {@code ageBand} from its {@code birthDate}, measured against the owner's
96	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} for 18 to 64, and
97	     * {@code SENIOR} for 65 and over. Returns {@code null} when no birth date is present, in which
98	     * case the field is absent from the response. The age in whole years is the number of complete
99	     * years between the birth date and the registration date (see {@link java.time.Period}); when the
100	     * registration date is somehow absent the current date is used as the reference.
101	     *
102	     * @param owner the owner being mapped
103	     * @return the derived age band, or {@code null} when no birth date is present
104	     */
105	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
106	        java.time.LocalDate birthDate = owner.getBirthDate();
107	        if (birthDate == null) {
108	            return null;
109	        }
110	        java.time.LocalDate reference = owner.getRegistrationDate() != null
111	            ? owner.getRegistrationDate() : java.time.LocalDate.now();
112	        int age = java.time.Period.between(birthDate, reference).getYears();
113	        if (age < 18) {
114	            return OwnerDto.AgeBandEnum.MINOR;
115	        }
116	        if (age < 65) {
117	            return OwnerDto.AgeBandEnum.ADULT;
118	        }
119	        return OwnerDto.AgeBandEnum.SENIOR;
120	    }
121	
122	    /**
123	     * Derives the owner's {@code locality} as the {@code REGION} segment of its {@code customerCode}
124	     * (the part before the {@code '-'}), which is the owner's canonical region code baked into the
125	     * region-and-hash identity {@code '<REGION>-<HASH8>'}. When no customer code is present (e.g. seed
126	     * data) it falls back to resolving the region directly from the owner's {@code postcode} and
127	     * {@code city} through the shared {@link Region#code(String, String)}. Reading the region from the
128	     * identity keeps the locality consistent with the code an owner is issued.
129	     *
130	     * @param owner the owner being mapped
131	     * @return the derived locality
132	     */
133	    default String locality(Owner owner) {
134	        String code = owner.getCustomerCode();
135	        if (code == null) {
136	            return Region.code(owner.getPostcode(), owner.getCity());
137	        }
138	        int dash = code.indexOf('-');
139	        return dash >= 0 ? code.substring(0, dash) : code;
140	    }
141	
142	    /**
143	     * Derives the owner's {@code timezone} as the IANA name for its {@link #locality(Owner) locality}
144	     * region, resolved through the shared fixed region-to-timezone table
145	     * ({@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
146	     * {@code QLD -> Australia/Brisbane}) in {@link Region#timezoneForCode(String)}. Deriving it from
147	     * the same locality keeps the timezone consistent with the region the owner is labelled with.
148	     * Returns {@code null} when the locality has no known timezone (such as an {@code UNKNOWN}
149	     * region), in which case the field is absent from the response.
150	     *
151	     * @param owner the owner being mapped
152	     * @return the derived IANA timezone name, or {@code null} when the region has no known timezone
153	     */
154	    default String timezone(Owner owner) {
155	        return Region.timezoneForCode(locality(owner));
156	    }
157	
158	    /**
159	     * Derives the owner's {@code membershipPoints} from the owner's factors. Starts at {@code 0},
160	     * adds {@code 2} when an email is present, adds {@code 1} when the owner's {@code namesakeCount}
161	     * is {@code 0}, adds {@code 2} for a household of {@code 3} or more (see
162	     * {@link Owner#getHouseholdSize()}), and adds {@code 3} when the owner's tenure &mdash; the number
163	     * of elapsed fiscal years between its {@code registrationDate} and the current date &mdash; exceeds
164	     * one fiscal year (see {@link #tenureFiscalYears(Owner)}).
165	     *
166	     * @param owner the owner being mapped
167	     * @return the derived membership points
168	     */
169	    default Integer membershipPoints(Owner owner) {
170	        int points = 0;
171	        if (hasEmail(owner)) {
172	            points += 2;
173	        }
174	        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
175	        if (uniqueName) {
176	            points += 1;
177	        }
178	        if (owner.getHouseholdSize() >= 3) {
179	            points += 2;
180	        }
181	        if (tenureFiscalYears(owner) > 1) {
182	            points += 3;
183	        }
184	        return points;
185	    }
186	
187	    /**
188	     * Maps the owner's {@code membershipPoints} to its numeric {@code membershipLevel}: level
189	     * {@code 1} for {@code 0-1} points, {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and
190	     * {@code 4} for {@code 6} or more points.
191	     *
192	     * @param owner the owner being mapped
193	     * @return the derived membership level, between {@code 1} and {@code 4}
194	     */
195	    default Integer membershipLevel(Owner owner) {
196	        int points = membershipPoints(owner);
197	        if (points <= 1) {
198	            return 1;
199	        }
200	        if (points <= 3) {
201	            return 2;
202	        }
203	        if (points <= 5) {
204	            return 3;
205	        }
206	        return 4;
207	    }
208	
209	    /**
210	     * Computes the owner's tenure as the number of elapsed fiscal years between the owner's
211	     * {@code registrationDate} and the current date: the fiscal year of "now" minus the fiscal year
212	     * of the registration date (see {@link #fiscalYearNumber(java.time.LocalDate)}). An owner
213	     * registered and read within the same fiscal year has a tenure of {@code 0}; each subsequent
214	     * fiscal year that has started adds one. Returns {@code 0} when no registration date is present,
215	     * so an owner without a registration date has no tenure.
216	     *
217	     * @param owner the owner being mapped
218	     * @return the owner's tenure in elapsed fiscal years, or {@code 0} when no registration date is present
219	     */
220	    default long tenureFiscalYears(Owner owner) {
221	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
222	        if (registrationDate == null) {
223	            return 0;
224	        }
225	        return (long) fiscalYearNumber(java.time.LocalDate.now()) - fiscalYearNumber(registrationDate);
226	    }
227	
228	    /**
229	     * Computes the calendar year that identifies the fiscal year containing {@code date}. The fiscal
230	     * year starts on 1 July and is labelled by the calendar year in which it starts, so a date on or
231	     * after 1 July belongs to that same year's fiscal year, while a date before 1 July belongs to the
232	     * previous year's fiscal year (e.g. {@code 2026-09-06} yields {@code 2026} and {@code 2026-06-15}
233	     * yields {@code 2025}).
234	     *
235	     * @param date the date whose fiscal year is wanted
236	     * @return the calendar year the fiscal year starts in
237	     */
238	    default int fiscalYearNumber(java.time.LocalDate date) {
239	        return date.getMonthValue() >= java.time.Month.JULY.getValue() ? date.getYear() : date.getYear() - 1;
240	    }
241	
242	    /**
243	     * Derives the owner's {@code fiscalYear}, formatted {@code 'FY<YY>'}, where {@code YY} is the last
244	     * two digits of the fiscal year of the (business-day-adjusted) {@code registrationDate} (e.g.
245	     * {@code 'FY26'}). Returns {@code null} when no registration date is present.
246	     *
247	     * @param owner the owner being mapped
248	     * @return the formatted fiscal year, or {@code null} when no registration date is present
249	     */
250	    default String fiscalYear(Owner owner) {
251	        if (owner.getRegistrationDate() == null) {
252	            return null;
253	        }
254	        return String.format("FY%02d", fiscalYearNumber(owner.getRegistrationDate()) % 100);
255	    }
256	
257	    /**
258	     * Builds the owner's {@code membershipNumber}, formatted {@code '<customerCode>-M<YY>'},
259	     * where {@code YY} is the last two digits of the fiscal year of the (business-day-adjusted)
260	     * {@code registrationDate} (e.g. {@code 'NSW-1A2B3C4D-M26'}). Returns {@code null} when either the
261	     * customer code or the registration date is absent.
262	     *
263	     * @param owner the owner being mapped
264	     * @return the formatted membership number, or {@code null} when it cannot be derived
265	     */
266	    default String membershipNumber(Owner owner) {
267	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
268	            return null;
269	        }
270	        return String.format("%s-M%02d", owner.getCustomerCode(), fiscalYearNumber(owner.getRegistrationDate()) % 100);
271	    }
272	
273	    /**
274	     * Computes the owner's {@code checkDigit}: a single Luhn check digit (0-9) over the digits
275	     * contained in the {@code customerCode} (non-digit characters, such as the {@code '<REGION>-'}
276	     * prefix, the separator and the hex letters {@code A-F}, are ignored). Returns {@code null} when
277	     * the customer code is absent.
278	     *
279	     * @param owner the owner being mapped
280	     * @return the Luhn check digit, or {@code null} when no customer code is present
281	     */
282	    default Integer checkDigit(Owner owner) {
283	        String code = owner.getCustomerCode();
284	        if (code == null) {
285	            return null;
286	        }
287	        int sum = 0;
288	        boolean dbl = true;
289	        for (int i = code.length() - 1; i >= 0; i--) {
290	            char c = code.charAt(i);
291	            if (c < '0' || c > '9') {
292	                continue;
293	            }
294	            int d = c - '0';
295	            if (dbl) {
296	                d *= 2;
297	                if (d > 9) {
298	                    d -= 9;
299	                }
300	            }
301	            sum += d;
302	            dbl = !dbl;
303	        }
304	        return (10 - (sum % 10)) % 10;
305	    }
306	
307	    /**
308	     * Formats the owner's stored E.164 {@code telephone} for human display: the country calling
309	     * code, a space, then the national-significant digits grouped in threes separated by spaces
310	     * (e.g. {@code '+61412345678'} becomes {@code '+61 412 345 678'}). The raw {@code telephone}
311	     * field keeps the unformatted E.164 value. The split between the country code and the national
312	     * digits mirrors the recognised calling codes of the {@code TelephoneNormalizer}: Australian
313	     * {@code +61} (9 national digits) and North American {@code +1} (10); an unrecognised or
314	     * malformed value falls back to a single leading digit. Returns the value unchanged when it is
315	     * {@code null}, blank, or not in E.164 form.
316	     *
317	     * @param owner the owner being mapped
318	     * @return the human-formatted telephone, or the raw value when it cannot be formatted
319	     */
320	    default String telephoneDisplay(Owner owner) {
321	        String telephone = owner.getTelephone();
322	        if (telephone == null || telephone.isBlank() || !telephone.startsWith("+")) {
323	            return telephone;
324	        }
325	        String digits = telephone.substring(1);
326	        int codeLength = (digits.startsWith("61") && digits.length() == 2 + 9) ? 2 : 1;
327	        String countryCode = digits.substring(0, codeLength);
328	        String national = digits.substring(codeLength);
329	        StringBuilder grouped = new StringBuilder();
330	        for (int i = 0; i < national.length(); i++) {
331	            if (i > 0 && i % 3 == 0) {
332	                grouped.append(' ');
333	            }
334	            grouped.append(national.charAt(i));
335	        }
336	        return "+" + countryCode + " " + grouped;
337	    }
