1	package org.springframework.samples.petclinic.rest.validation;
2	
3	import java.util.Locale;
4	import java.util.Set;
5	
6	import org.springframework.stereotype.Component;
7	
8	/**
9	 * Holds the blocklist of disposable email domains and decides whether a given owner email uses one.
10	 * A disposable domain is a throwaway mail provider ({@code mailinator.com}, {@code tempmail.com},
11	 * {@code guerrillamail.com}) that owners must not register with. Keeping the blocklist and the
12	 * matching logic in one place lets the create endpoint treat "is this a disposable address" as a
13	 * single opaque question.
14	 *
15	 * <p>Matching is case-insensitive (using {@link Locale#ROOT} so it is locale-independent) and looks
16	 * only at the domain part after the final {@code '@'}; syntactic validity of the address is enforced
17	 * separately by Bean Validation ({@code @Email} on the owner fields), so a malformed or missing
18	 * address is rejected before this runs and is treated here as not disposable.
19	 */
20	@Component
21	public class DisposableEmailDomains {
22	
23	    private static final Set<String> BLOCKED_DOMAINS = Set.of(
24	        "mailinator.com", "tempmail.com", "guerrillamail.com");
25	
26	    /**
27	     * Reports whether the given email's domain is on the disposable-domain blocklist. A {@code null},
28	     * blank, or {@code '@'}-less value has no comparable domain and is treated as not disposable.
29	     *
30	     * @param email the raw email value from the request, or {@code null} when omitted
31	     * @return {@code true} when the email's domain is blocklisted
32	     */
33	    public boolean isDisposable(String email) {
34	        if (email == null) {
35	            return false;
36	        }
37	        int at = email.lastIndexOf('@');
38	        if (at < 0) {
39	            return false;
40	        }
41	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
42	        return BLOCKED_DOMAINS.contains(domain);
43	    }
44	}
