10	/**
11	 * Computes the SHA-256 hashes behind the derived identifiers that fingerprint owner fields. Keeping
12	 * the hashing in one place lets the create endpoint treat "hash these owner fields" as an opaque
13	 * primitive - it supplies the value to hash and how much of the digest it wants, and every derived
14	 * identifier is produced by the same algorithm, differing only in the value it hashes and how the
15	 * digest is presented.
16	 *
17	 * <p>The digest is taken over the UTF-8 bytes of the input; {@link #hexPrefix(String, int)} keeps a
18	 * leading run of upper-case hex characters, as used by the household-scoped {@code householdId} and
19	 * the {@code customerCode}'s hash segment.
20	 */
21	@Component
22	public class Sha256Hasher {
23	
24	    /**
25	     * The leading {@code length} upper-case hex characters of the SHA-256 digest of the UTF-8 bytes
26	     * of {@code input}. Used by the derived identifiers that keep only a short hash prefix - the
27	     * household-scoped {@code householdId} and the {@code customerCode}'s {@code HASH8} segment - so
28	     * each is produced by the same algorithm and differs only in the value it hashes and the number
29	     * of hex characters it keeps.
30	     *
31	     * @param input the value to hash
32	     * @param length the number of leading hex characters to keep
33	     * @return the leading {@code length} upper-case hex characters of the SHA-256 digest
34	     */
35	    public String hexPrefix(String input, int length) {
36	        return hex(input).substring(0, length).toUpperCase(Locale.ROOT);
37	    }
38	
39	    /**
40	     * The full lower-case hex encoding of the SHA-256 digest of the UTF-8 bytes of {@code input}.
41	     * This is the shared digest computation; callers that keep only a leading, upper-case run of it
42	     * go through {@link #hexPrefix(String, int)}.
43	     *
44	     * @param input the value to hash
45	     * @return the SHA-256 digest as a lower-case hex string
46	     */
47	    private String hex(String input) {
48	        try {
49	            byte[] digest = MessageDigest.getInstance("SHA-256")
50	                .digest(input.getBytes(StandardCharsets.UTF_8));
51	            StringBuilder sb = new StringBuilder(digest.length * 2);
52	            for (byte b : digest) {
53	                sb.append(String.format("%02x", b));
54	            }
55	            return sb.toString();
56	        } catch (NoSuchAlgorithmException e) {
57	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
58	        }
59	    }
60	}
